#!/usr/bin/env python
"""Build docs/evidence_manifest.json: claim -> report -> result files -> figure / table source.

Three inputs are joined on the block code that the page puts on every evidence block
(``data-evidence="F1-A"`` in docs/index.html):

* docs/index.html          which headings, datasets, source label, figures and images a block shows
* docs/evidence/*.json     the verified evidence entries (claim, metric, numbers with source file and locator)
* docs/data/figures.json   for every figure: the module that builds it and the result files it reads

    python docs/build/build_figures.py && python docs/build/build_manifest.py

It also writes docs/evidence_index.md, the same mapping as a table for people.

The script fails when the page shows a figure that has no data, or a block that has no evidence entry.
"""
from __future__ import annotations

import json
import sys
from html.parser import HTMLParser
from pathlib import Path

DOCS_DIR = Path(__file__).resolve().parents[1]
PAGE = DOCS_DIR / "index.html"
EVIDENCE_DIR = DOCS_DIR / "evidence"
FIGURES = DOCS_DIR / "data" / "figures.json"
IMAGES = EVIDENCE_DIR / "images.json"
OUT = DOCS_DIR / "evidence_manifest.json"
OUT_INDEX = DOCS_DIR / "evidence_index.md"

VOID = {"meta", "link", "br", "hr", "img", "input", "source"}
FINDING_OF = {"MOTIVATION": "Motivation", "HYP": "Current hypothesis"}
STATUS_OF = {"MOTIVATION": "motivation", "HYP": "hypothesis: experiment in progress, no result"}


class PageBlocks(HTMLParser):
    """Collect what the page shows inside each element that carries ``data-evidence``."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.stack: list[tuple[str, str | None, str | None]] = []   # (tag, block, capture role)
        self.blocks: dict[str, dict] = {}
        self.buffer: list[str] = []

    def _block(self) -> str | None:
        return self.stack[-1][1] if self.stack else None

    def _entry(self, block: str) -> dict:
        return self.blocks.setdefault(block, {"headings": [], "datasets": [], "source_labels": [], "figures": [], "images": []})

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attr = dict(attrs)
        block = attr.get("data-evidence") or self._block()
        classes = (attr.get("class") or "").split()
        if block:
            entry = self._entry(block)
            if tag == "figure" and attr.get("data-fig") and attr["data-fig"] not in entry["figures"]:
                entry["figures"].append(attr["data-fig"])
            if tag == "img" and attr.get("src") and attr["src"] not in entry["images"]:
                entry["images"].append(attr["src"])
        if tag in VOID:
            return
        role = None
        if "verdict" in classes:
            role = "skip"                       # the outcome badge inside a heading is not part of the heading
        elif block and tag == "h3":
            role = "heading"
        elif block and tag == "h2" and "question" in classes:
            role = "heading"
        elif block and "chip" in classes:
            role = "dataset"
        elif block and "src" in classes:
            role = "source"
        if role and role != "skip":
            self.buffer = []
        self.stack.append((tag, block, role))

    def handle_startendtag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in ("figure", "img"):
            self.handle_starttag(tag, attrs)
            if tag not in VOID:
                self.stack.pop()

    def handle_endtag(self, tag: str) -> None:
        if tag in VOID or not self.stack:
            return
        opened, block, role = self.stack.pop()
        if opened != tag:
            raise ValueError(f"unbalanced HTML near line {self.getpos()[0]}: <{opened}> closed by </{tag}>")
        if role and role != "skip" and block:
            text = " ".join("".join(self.buffer).split())
            entry = self._entry(block)
            key = {"heading": "headings", "dataset": "datasets", "source": "source_labels"}[role]
            if role == "source":
                text = text.removeprefix("Source:").strip()
            if text and text not in entry[key]:
                entry[key].append(text)

    def handle_data(self, data: str) -> None:
        roles = [role for _, _, role in self.stack if role]
        if roles and "skip" not in roles:
            self.buffer.append(data)


def finding_of(block: str) -> str:
    if block in FINDING_OF:
        return FINDING_OF[block]
    return "Finding " + block[1]            # "F1-A" -> "Finding 1"


def write_index(blocks: list[dict]) -> None:
    """The manifest as a table: one section per evidence block."""
    lines = ["# Evidence index", "",
             "Generated by `docs/build/build_manifest.py` from `index.html`, `evidence/*.json` and `data/figures.json`.",
             "Result files are relative to the result root; `docs/data/sources/` holds snapshots of the small ones.", ""]
    for block in blocks:
        lines += [f"## `{block['block']}` · {block['finding']} · {block['status']}", ""]
        for heading in block["page_headings"]:
            lines.append(f"- on the page: **{heading}**")
        lines.append(f"- datasets on the page: {', '.join(block['datasets_on_page']) or '–'}")
        lines.append(f"- source label: {'; '.join(block['source_labels']) or '–'}")
        reports = sorted({entry["report"] for entry in block["evidence"]})
        for report in reports:
            lines.append(f"- report: `{report}`")
        n_numbers = sum(len(entry["numbers"]) for entry in block["evidence"])
        files = sorted({entry["evidence_file"] for entry in block["evidence"]})
        lines.append(f"- verified claims: {len(block['evidence'])} with {n_numbers} numbers, in {', '.join(f'`{f}`' for f in files)}")
        if block["figures"]:
            lines += ["", "| figure | built by | reads |", "|---|---|---|"]
            for fig in block["figures"]:
                reads = "<br>".join(f"`{src['path']}`" for src in fig["source_files"])
                lines.append(f"| `{fig['id']}` | `{fig['module']}` | {reads} |")
        for image in block["images"]:
            lines += ["", f"Image `{image['file']}` from `{image['from']}` ({image['edit']})."]
        lines.append("")
    OUT_INDEX.write_text("\n".join(lines), encoding="utf-8")


def main() -> int:
    parser = PageBlocks()
    parser.feed(PAGE.read_text(encoding="utf-8"))
    figures = json.loads(FIGURES.read_text(encoding="utf-8"))["figures"]
    images = json.loads(IMAGES.read_text(encoding="utf-8")) if IMAGES.is_file() else {}

    entries_by_block: dict[str, list[dict]] = {}
    not_claimed: dict[str, list[str]] = {}
    verification: dict[str, dict] = {}
    for path in sorted(EVIDENCE_DIR.glob("*.json")):
        if path.name == IMAGES.name:
            continue
        unit = json.loads(path.read_text(encoding="utf-8"))
        for entry in unit["entries"]:
            item = dict(entry)
            item["evidence_file"] = f"docs/evidence/{path.name}"
            entries_by_block.setdefault(entry["block"], []).append(item)
            for rule in unit["do_not_claim"]:
                if rule not in not_claimed.setdefault(entry["block"], []):
                    not_claimed[entry["block"]].append(rule)
        if unit.get("verification"):
            v = unit["verification"]
            verification[path.stem] = {k: v[k] for k in ("reliability", "numbers_confirmed", "numbers_checked",
                                                          "claims_supported_as_extracted", "claims_checked")}

    problems: list[str] = []
    blocks = []
    for block, shown in parser.blocks.items():
        entries = entries_by_block.get(block, [])
        if not entries:
            problems.append(f"block {block} is on the page but has no evidence entry")
        block_figures = []
        for fig_id in shown["figures"]:
            if fig_id not in figures:
                problems.append(f"block {block}: figure {fig_id} has no data")
                continue
            fig = figures[fig_id]
            block_figures.append({"id": fig_id, "type": fig["type"], "title": fig["title"], "module": fig["module"],
                                  "source_files": fig["sources"], "note": fig["note"]})
        block_images = []
        for src in shown["images"]:
            if src not in images:
                problems.append(f"block {block}: image {src} has no provenance entry in docs/evidence/images.json")
                continue
            block_images.append({"file": f"docs/{src}", **images[src]})
        blocks.append({
            "block": block,
            "finding": finding_of(block),
            "status": STATUS_OF.get(block, "completed finding"),
            "page_headings": shown["headings"],
            "datasets_on_page": shown["datasets"],
            "source_labels": shown["source_labels"],
            "figures": block_figures,
            "images": block_images,
            "evidence": [{"finding": finding_of(block), **entry} for entry in entries],
            "do_not_claim": not_claimed.get(block, []),
        })

    if problems:
        print("\n".join(problems), file=sys.stderr)
        return 1

    manifest = {
        "title": "Evidence manifest: What Should a Temporal Contact Generator Actually Model?",
        "how_to_read": ("One object per evidence block of docs/index.html. 'evidence' lists the verified claims with their "
                        "report, result files, metric and numbers (value, source file, locator); 'figures' lists every chart "
                        "of the block with the module that builds it and the result files it reads. Paths without a leading "
                        "'docs/' or 'scripts/' are relative to the result root."),
        "result_root": "/result/uhnam/dexcore (the server's result tree; small source tables are snapshotted under docs/data/sources/)",
        "verification": verification,
        "blocks": blocks,
    }
    OUT.write_text(json.dumps(manifest, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    write_index(blocks)
    n_entries = sum(len(b["evidence"]) for b in blocks)
    n_numbers = sum(len(e["numbers"]) for b in blocks for e in b["evidence"])
    print(f"wrote {OUT.relative_to(DOCS_DIR.parent)}: {len(blocks)} blocks, {n_entries} claims, {n_numbers} numbers", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
